% We calculate the coefficients of a and b in 1=a/Weight+b*Height for this
% dataset
Age_28_Czech = 50:90;
Coefficient_a_Female_1_28_Czech = [];
Coefficient_b_Female_1_28_Czech = [];
Coefficient_a_Male_1_28_Czech = [];
Coefficient_b_Male_1_28_Czech = [];

% For Female
