% We calculate the coefficients of a and b in 1=a/Weight+b*Height for this
% dataset
Age_35_Estonia = 50:90;
Coefficient_a_Female_1_35_Estonia = [];
Coefficient_b_Female_1_35_Estonia = [];
Coefficient_a_Male_1_35_Estonia = [];
Coefficient_b_Male_1_35_Estonia = [];

% For Female
% Age 50
X_data = (Female_data_50(:,1)/100).^c; % Height (m)
Y_data = Female_data_50(:,2); % Weight
Z_data= X_data.*Y_data; % Height^c*Weight
PP = polyfit(Z_data,Y_data,1); % linear fitting
Coefficient_a_Female_1_35_Estonia = [Coefficient_a_Female_1_35_Estonia PP(2)];
Coefficient_b_Female_1_35_Estonia = [Coefficient_b_Female_1_35_Estonia PP(1)];
